import { existsSync, mkdirSync, mkdtempSync, readFileSync, writeFileSync } from 'node:fs';
import { createServer, type Server } from 'node:http';
import type { AddressInfo } from 'node:net';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { afterAll, beforeAll, beforeEach, describe, expect, it } from 'vitest';
import { sha256 } from './fetch';
import { fetchImages } from './fetch-images';

// Generated bytes standing in for images: not even a test fixture may be a game image.
const bytes = {
  'weapon/Wst_A_00.png': Buffer.from('kit A'),
  'gear/Hed_G1.png': Buffer.from('hat G1'),
};
let requests: string[] = [];
let serveWrong = false;
let server: Server;
let base = '';

beforeAll(async () => {
  server = createServer((req, res) => {
    const path = (req.url ?? '').replace(/^\/images\//, '');
    requests.push(path);
    const body = bytes[path as keyof typeof bytes];
    if (!body) {
      res.writeHead(404);
      return res.end();
    }
    res.end(serveWrong ? Buffer.from('truncated') : body);
  });
  await new Promise<void>((r) => server.listen(0, r));
  base = `http://localhost:${(server.address() as AddressInfo).port}/`;
});
afterAll(() => new Promise<void>((r) => server.close(() => r())));

let root = '';
let cache = '';
let out = '';
beforeEach(() => {
  requests = [];
  serveWrong = false;
  root = mkdtempSync(join(tmpdir(), 'catalogue-'));
  cache = mkdtempSync(join(tmpdir(), 'cache-'));
  out = mkdtempSync(join(tmpdir(), 'public-'));
  mkdirSync(join(root, '1.0.0'));
  writeFileSync(
    join(root, '1.0.0', 'images.lock.json'),
    JSON.stringify(Object.fromEntries(Object.entries(bytes).map(([p, b]) => [p, sha256(b)]))),
  );
});

const run = () =>
  fetchImages({
    catalogueRoot: root,
    cacheDir: cache,
    outDir: out,
    baseFor: () => base,
    retryDelayMs: 1,
  });

describe('fetchImages', () => {
  it('publishes every locked image under its catalogue version', async () => {
    await run();
    expect(readFileSync(join(out, '1.0.0', 'weapon/Wst_A_00.png'))).toEqual(
      bytes['weapon/Wst_A_00.png'],
    );
    expect(readFileSync(join(out, '1.0.0', 'gear/Hed_G1.png'))).toEqual(bytes['gear/Hed_G1.png']);
  });

  it('downloads nothing on a second build: the cache holds every verified image', async () => {
    await run();
    requests = [];
    const second = await run();
    expect(requests).toEqual([]);
    expect(second).toEqual({ images: 2, downloaded: 0 });
  });

  it('never trusts a cached file: one altered on disk is fetched again', async () => {
    await run();
    writeFileSync(join(cache, sha256(bytes['gear/Hed_G1.png'])), 'altered on disk');
    requests = [];
    await run();
    expect(requests).toEqual(['gear/Hed_G1.png']);
    expect(readFileSync(join(out, '1.0.0', 'gear/Hed_G1.png'))).toEqual(bytes['gear/Hed_G1.png']);
  });

  it('stops on a download that is not the locked image, naming it, and keeps nothing of it', async () => {
    serveWrong = true;
    await expect(run()).rejects.toThrow(
      `game-images: weapon/Wst_A_00.png does not match its digest: expected ${sha256(bytes['weapon/Wst_A_00.png'])}, ` +
        `received ${sha256(Buffer.from('truncated'))}`,
    );
    expect(existsSync(join(cache, sha256(bytes['weapon/Wst_A_00.png'])))).toBe(false);
  });

  it('names the image and its address when it cannot be downloaded', async () => {
    writeFileSync(
      join(root, '1.0.0', 'images.lock.json'),
      JSON.stringify({ 'gear/Hed_G9.png': 'ab' }),
    );
    await expect(run()).rejects.toThrow(
      `could not fetch images/gear/Hed_G9.png from ${base}images/gear/Hed_G9.png: HTTP 404`,
    );
  });
});
